/**
 * The notices the wheel ships name every package the page bundles.
 *
 * `third-party-notices.txt` is written by `build.mjs` from esbuild's metafile,
 * and it is committed with the rest of the built assets. The first test bundles
 * the page again with the same options and asks whether the committed file has
 * a section for each package that bundle carries, at the version it carries,
 * and for nothing else. A dependency added, bumped or dropped without the
 * assets being rebuilt fails here, and so does a bundled package that has
 * somehow lost its notice.
 *
 * The others hold the rules the notices are generated by: a bundled package
 * with no licence file of its own is refused by name; a package carried inside
 * another's distributed file is found through that file's source map; and a
 * notice a bundled file points at -- a `.LEGAL.txt` beside it -- is carried
 * under its own name.
 */

import { mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";

import { build, type Metafile } from "esbuild";
import { afterEach, describe, expect, it } from "vitest";

import { bundledPackages, bundleOptions, FONT_FAMILIES } from "../bundle.mjs";

const NOTICES = "python/gaspatchio_viewer/assets/third-party-notices.txt";
const RULE = "=".repeat(78);

/** The first line of every section in a notices file: "name version", or a font family. */
function sectionsOf(text: string): string[] {
  const lines = text.split("\n");
  return lines.flatMap((line, at) =>
    line === RULE && lines[at + 2]?.startsWith("Licence: ") ? [lines[at + 1] ?? ""] : [],
  );
}

/** A metafile saying one output took bytes from each of `inputs`. */
function metafileOf(...inputs: string[]): Metafile {
  return {
    inputs: {},
    outputs: {
      "dist/viewer.js": {
        bytes: 100,
        inputs: Object.fromEntries(inputs.map((input) => [input, { bytesInOutput: 10 }])),
        imports: [],
        exports: [],
      },
    },
  };
}

const made: string[] = [];

/** A directory holding the files named, each with the text given. */
function tree(files: Record<string, string>): string {
  const root = mkdtempSync(join(tmpdir(), "notices-"));
  made.push(root);
  for (const [path, text] of Object.entries(files)) {
    mkdirSync(dirname(join(root, path)), { recursive: true });
    writeFileSync(join(root, path), text);
  }
  return root;
}

afterEach(() => {
  for (const root of made.splice(0)) rmSync(root, { recursive: true, force: true });
});

describe("the third-party notices", () => {
  it("have a section for every package the bundle carries, and for nothing else", async () => {
    const result = await build({ ...bundleOptions, write: false, metafile: true, logLevel: "silent" });
    const bundled = bundledPackages(result.metafile).map((pkg) => `${pkg.name} ${pkg.version}`);
    const families = new Set(FONT_FAMILIES.map((family) => family.family));
    const sections = sectionsOf(readFileSync(NOTICES, "utf8")).filter((name) => !families.has(name));

    const unnoticed = bundled.filter((entry) => !sections.includes(entry));
    expect(unnoticed, `in the bundle with no notice in ${NOTICES}; run node build.mjs --copy-assets`).toEqual([]);
    expect(sections, `${NOTICES} names packages the bundle no longer carries`).toEqual(bundled);
    expect(bundled.length).toBeGreaterThan(0);
  });

  it("refuse a bundled package that ships no licence file, by name", () => {
    const root = tree({
      "node_modules/unlicensed/package.json": JSON.stringify({ version: "1.2.3", license: "MIT" }),
      "node_modules/unlicensed/index.js": "export const x = 1;\n",
    });
    expect(() => bundledPackages(metafileOf("node_modules/unlicensed/index.js"), root)).toThrow(
      /unlicensed@1\.2\.3 is in the page's bundle and ships no licence file/,
    );
  });

  it("find a package carried inside another's distributed file through its source map", () => {
    const root = tree({
      "node_modules/outer/package.json": JSON.stringify({ version: "2.0.0", license: "MIT" }),
      "node_modules/outer/LICENSE": "outer's licence\n",
      "node_modules/outer/dist/index.js": "export const y = 2;\n//# sourceMappingURL=index.js.map\n",
      "node_modules/outer/dist/index.js.map": JSON.stringify({
        version: 3,
        sources: ["../src/index.ts", "../node_modules/inner/lib/index.ts"],
        mappings: "",
      }),
      "node_modules/inner/package.json": JSON.stringify({ version: "3.0.0", license: "ISC" }),
      "node_modules/inner/LICENSE": "inner's licence\n",
    });
    const found = bundledPackages(metafileOf("node_modules/outer/dist/index.js"), root);
    expect(found.map((pkg) => [pkg.name, pkg.version, pkg.licence, pkg.via])).toEqual([
      ["inner", "3.0.0", "ISC", "outer"],
      ["outer", "2.0.0", "MIT", null],
    ]);
    expect(found[0]?.licenceFiles).toEqual([{ name: "LICENSE", text: "inner's licence\n" }]);
  });

  it("carry the notice a bundled file points at, under the name it points at", () => {
    const root = tree({
      "node_modules/pointed/package.json": JSON.stringify({ version: "4.0.0", license: "MIT" }),
      "node_modules/pointed/LICENSE": "pointed's licence\n",
      "node_modules/pointed/dist/pointed.esm.js":
        "/*! For license information please see pointed.esm.js.LEGAL.txt */\nexport const z = 3;\n",
      "node_modules/pointed/dist/pointed.esm.js.LEGAL.txt": "the notice the file points at\n",
    });
    const [found] = bundledPackages(metafileOf("node_modules/pointed/dist/pointed.esm.js"), root);
    expect(found?.licenceFiles).toEqual([
      { name: "LICENSE", text: "pointed's licence\n" },
      { name: "dist/pointed.esm.js.LEGAL.txt", text: "the notice the file points at\n" },
    ]);
  });
});
